def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 if v == 4 else v for v in row] for row in grid]
    barrier_rows = [r for r, row in enumerate(grid) if row and all(v == 2 for v in row)]
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v != 4:
                continue
            nr = min(r + 1, h - 1)
            out[nr][c] = 4
            if nr + 1 in barrier_rows:
                d = 1
                while nr - d >= 0:

                    if c - d >= 0:
                        out[nr - d][c - d] = 4
                    if c + d < w:
                        out[nr - d][c + d] = 4
                    d += 1
    return out
